sourcesContent:
import Card from '../components/Card';

const domains = [
  { title: 'AI & ML', description: 'Machine learning models, data pipelines and intelligent systems.' },
  { title: 'Web Development', description: 'Frontend, backend, and full-stack app delivery.' },
  { title: 'Cloud & DevOps', description: 'Cloud services automation, CI/CD, and infrastructure as code.' },
  { title: 'Cybersecurity', description: 'Secure design, risk management, and defensive tools.' },
];

export default function DomainsPage() {
  return (
    <div className="space-y-8">
      <Card title="Domain selection" description="Choose a specialization that best fits your goals and study rhythm.">
        <div className="grid gap-5 sm:grid-cols-2">
          {domains.map((domain) => (
            <div key={domain.title} className="rounded-[2rem] border border-slate-800 bg-slate-950/90 p-6 hover:border-cyan-500/40 hover:bg-slate-900/95">
              <h3 className="text-xl font-semibold text-white">{domain.title}</h3>
              <p className="mt-3 text-slate-400">{domain.description}</p>
              <div className="mt-5 inline-flex items-center rounded-full bg-slate-800 px-4 py-2 text-sm text-slate-300">Select path</div>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}
